@namespace sv_7ed820e8a15b43a38729d4d7734b606a.Components.Pages.Apply

<nav aria-label="Application steps" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between m-0 p-0 position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = step > CurrentStep && !isCompleted;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
                role="button"
                @onclick="() => OnStepClick(step)"
                style="cursor: @(isCompleted ? "pointer" : "default"); opacity: @(isFuture ? "0.4" : "1")">
                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light border")">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="@(isCurrent ? "fw-bold text-primary" : "")">@StepNames[step]</small>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator .step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.85rem;
    font-weight: 600;
    transition: all 0.2s;
}

.step-indicator .step-item.active .step-circle {
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.25);
}

.step-indicator .step-item.completed .step-circle {
    box-shadow: 0 0 0 3px rgba(25, 135, 84, 0.25);
}

@namespace sv_7ed820e8a15b43a38729d4d7734b606a.Components.Pages.Apply
@using sv_7ed820e8a15b43a38729d4d7734b606a.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @ReferenceNumber</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>
